def bundle_evolution_checkpoint(
    report: Any, start: str, end: str
) -> dict[str, Any]:
    """Cut a stage-window proof out of a full bundle evolution report.

    Pure function: it only processes its arguments, accesses neither history
    nor files, and never mutates an input object at any level.

    ``start`` and ``end`` must be valid UTC seconds with ``start <= end`` and
    both must be the ``at`` of stages that actually exist in ``report`` (an
    illegal time, a missing boundary, or a reversed window raises
    ``ValueError``). ``report`` must be a complete, fully verifiable
    :func:`checkpoint_chain_checkpoint_bundle_evolution` report: any
    structural, time, ordering, window-proof, member-chain, adjacent-diff,
    stage-link, stage-digest, or root forgery raises ``ValueError`` before
    anything is produced.

    The proof covers the continuous run of stages from ``start`` through
    ``end`` inclusive, with no stage skipped, reordered, or rewritten.
    Returns a deep copy containing exactly the keys ``start``, ``end``,
    ``anchor``, ``stages``, ``commitment`` in that order. When the window
    begins at the report's first stage, ``anchor`` is 64 ASCII ``0``
    characters; otherwise it is the immediately preceding stage's ``digest``.
    ``stages`` are independent deep copies of the full window stages, each
    still following the published chain window proof bundle, diff, and
    stage-chain contracts; the first stage of a non-head window keeps its
    original ``diff`` and the bundle on its front side, so even a
    single-stage window can be recomputed without the report outside the
    window. ``commitment`` is the last window stage's ``digest`` and also
    equals the original report ``root`` when the window reaches the report's
    end. Equal-valued inputs yield byte-identical results.
    """
    start = _check_time(start, "start")
    end = _check_time(end, "end")
    if start > end:
        raise ValueError(f"start must not be after end: {start!r} > {end!r}")
    report_root, stages = (
        _normalize_verified_checkpoint_chain_checkpoint_bundle_evolution(
            report, "report"
        )
    )
    self_expected = {
        "root": report_root,
        "stages": [
            {
                "at": stage["at"],
                "bundle_root": stage["bundle_root"],
                "diff_digest": (
                    None if stage["diff"] is None else stage["diff"]["digest"]
                ),
            }
            for stage in stages
        ],
    }
    if not verify_checkpoint_chain_checkpoint_bundle_evolution(
        report, self_expected
    ):
        raise ValueError(
            "report must be a fully verifiable bundle evolution report"
        )
    ats = [stage["at"] for stage in stages]
    if start not in ats:
        raise ValueError("start must be the at of a stage that exists in report")
    if end not in ats:
        raise ValueError("end must be the at of a stage that exists in report")
    first_index = ats.index(start)
    last_index = ats.index(end)
    anchor = (
        _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS
        if first_index == 0
        else stages[first_index - 1]["digest"]
    )
    window = stages[first_index : last_index + 1]
    proof_stages = [
        {
            "at": stage["at"],
            "bundle": copy.deepcopy(stage["bundle"]),
            "diff": copy.deepcopy(stage["diff"]),
            "previous": stage["previous"],
            "digest": stage["digest"],
        }
        for stage in window
    ]
    return {
        "start": start,
        "end": end,
        "anchor": anchor,
        "stages": proof_stages,
        "commitment": window[-1]["digest"],
    }


def _normalize_verified_bundle_evolution_checkpoint(
    proof: Any, field: str = "proof"
) -> dict[str, Any]:
    """Run every structural and semantic check on a bundle window proof.

    Enforces the :func:`bundle_evolution_checkpoint` proof contract: exact
    key sets, valid ``start``/``end`` timestamps with ``start <= end``,
    hex64 ``anchor``/``commitment``, a non-empty strictly increasing stage
    chain, fully valid per-stage chain window proof bundles, and adjacent
    diff credentials that reproduce their neighboring bundles. The first
    stage follows the genesis rule (``previous`` of 64 zeroes and ``null``
    diff) or carries the full front-side chain window proof bundle diff
    whose ``after`` bundle reproduces the first stage. Window disorder, an
    illegal change item, or an adjacent diff that does not correspond raises
    ``ValueError``. False declared summaries are carried back as data
    (``bundle_truthful``, ``diff_complete``, and the validated carried-diff
    members) so they yield ``False`` only after every input validates.
    Boundary agreement of ``start``/``end`` with the first/last stage ``at``
    is reported via ``boundaries_ok`` rather than raised. The input is never
    mutated.
    """
    if not isinstance(proof, dict) or set(proof) != set(
        _BUNDLE_EVOLUTION_CHECKPOINT_REPORT_KEYS
    ):
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, anchor, stages, commitment"
        )
    start = _check_time(proof["start"], f"{field}.start")
    end = _check_time(proof["end"], f"{field}.end")
    if start > end:
        raise ValueError(f"{field}.start must not be after {field}.end")
    anchor = _check_hex64(proof["anchor"], f"{field}.anchor")
    commitment = _check_hex64(proof["commitment"], f"{field}.commitment")
    raw_stages = proof["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    normalized_stages: list[dict[str, Any]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        stage_field = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != set(
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_STAGE_KEYS
        ):
            raise ValueError(
                f"{stage_field} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = _check_time(stage["at"], f"{stage_field}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{stage_field}.at must be strictly greater than the "
                "preceding stage at"
            )
        previous_digest = _check_hex64(
            stage["previous"], f"{stage_field}.previous"
        )
        digest = _check_hex64(stage["digest"], f"{stage_field}.digest")
        bundle_root, bundle_members = (
            _normalize_verified_checkpoint_chain_checkpoint_bundle(
                stage["bundle"], f"{stage_field}.bundle"
            )
        )
        bundle = _canonical_checkpoint_bundle_from_members(
            bundle_root, bundle_members
        )
        bundle_truthful = _chain_checkpoint_bundle_is_truthful(
            bundle_root, bundle_members
        )

        carried_diff: tuple[
            dict[str, Any],
            list[dict[str, Any]],
            list[dict[str, Any]],
            list[dict[str, Any]],
            bool,
        ] | None = None
        if index == 0 and previous_digest == (
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS
        ):
            if stage["diff"] is not None:
                raise ValueError(
                    f"{stage_field}.diff must be null at the genesis stage"
                )
            diff: dict[str, Any] | None = None
            diff_complete = True
        elif index == 0:
            diff_content, before_members, after_members, change_entries, complete = (
                _normalize_verified_chain_checkpoint_diff_report(
                    stage["diff"], f"{stage_field}.diff"
                )
            )
            if diff_content["after_root"] != bundle_root:
                raise ValueError(
                    f"{stage_field}.diff.after_root must equal this stage "
                    "bundle root"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["after"]
            ) != _chain_checkpoint_bundle_semantics(bundle):
                raise ValueError(
                    f"{stage_field}.diff.after must reproduce this stage bundle"
                )
            diff = diff_content
            diff_complete = complete
            carried_diff = (
                diff_content,
                before_members,
                after_members,
                change_entries,
                complete,
            )
        else:
            preceding = normalized_stages[-1]
            diff_content, _before_members, _after_members, _changes, complete = (
                _normalize_verified_chain_checkpoint_diff_report(
                    stage["diff"], f"{stage_field}.diff"
                )
            )
            if diff_content["before_root"] != preceding["bundle_root"]:
                raise ValueError(
                    f"{stage_field}.diff.before_root must equal the preceding "
                    "stage bundle root"
                )
            if diff_content["after_root"] != bundle_root:
                raise ValueError(
                    f"{stage_field}.diff.after_root must equal this stage "
                    "bundle root"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["before"]
            ) != _chain_checkpoint_bundle_semantics(preceding["bundle"]):
                raise ValueError(
                    f"{stage_field}.diff.before must reproduce the preceding "
                    "stage bundle"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["after"]
            ) != _chain_checkpoint_bundle_semantics(bundle):
                raise ValueError(
                    f"{stage_field}.diff.after must reproduce this stage bundle"
                )
            diff = diff_content
            diff_complete = complete

        normalized_stages.append(
            {
                "at": at,
                "bundle": bundle,
                "bundle_root": bundle_root,
                "bundle_truthful": bundle_truthful,
                "diff": diff,
                "diff_complete": diff_complete,
                "carried_diff": carried_diff,
                "previous": previous_digest,
                "digest": digest,
            }
        )
        previous_at = at

    boundaries_ok = (
        start == normalized_stages[0]["at"]
        and end == normalized_stages[-1]["at"]
    )
    return {
        "start": start,
        "end": end,
        "anchor": anchor,
        "commitment": commitment,
        "stages": normalized_stages,
        "boundaries_ok": boundaries_ok,
    }


def verify_bundle_evolution_checkpoint(proof: Any, expected: Any) -> bool:
    """Verify a :func:`bundle_evolution_checkpoint` proof without the report.

    Pure function: it only inspects its arguments, touches neither history
    nor files, and never mutates an input object at any level.

    ``proof`` must be a dict with exactly the keys ``start``, ``end``,
    ``anchor``, ``stages``, ``commitment``; ``start``/``end`` must be valid
    UTC seconds with ``start <= end`` and ``anchor``/``commitment`` 64
    lowercase hexadecimal characters. ``stages`` must be a non-empty list of
    full bundle evolution stages whose ``at`` values are strictly
    increasing, whose chain window proof bundles pass every bundle
    structural and embedded-proof semantic check, and whose diffs correspond
    to their neighbors: the genesis stage carries 64 zeroes as ``previous``
    and a ``null`` diff; any other first stage keeps its front-side chain
    window proof bundle diff whose ``after`` bundle reproduces that stage,
    and every later diff must reproduce the preceding and current bundles.
    ``expected`` must have exactly the keys ``start``, ``end``, ``anchor``,
    ``commitment`` and is validated the same way. Exact key sets, times,
    digest formats, stage order, and every embedded credential semantic are
    checked on both inputs first; an illegal structure, disorder, an invalid
    change item, or an adjacent diff that does not correspond raises
    ``ValueError``.

    Only afterwards are values recomputed rather than trusted: every bundle
    chain (including the front-side bundle carried by a non-head first-stage
    diff), the first stage digest seeded from ``anchor`` (the carried diff
    recomputed from its before/after bundles and change proofs), each later
    adjacent :func:`checkpoint_chain_checkpoint_bundle_diff` credential,
    every ``previous``/``digest`` stage link, and the terminal
    ``commitment``. Returns ``False`` for a broken link, a wrong anchor, a
    skipped stage, a tampered diff (including a structurally legal change
    list that omits or invents a change), a boundary mismatch, or any
    ``expected`` disagreement after the structures are legal; otherwise
    ``True``.
    """
    normalized = _normalize_verified_bundle_evolution_checkpoint(proof, "proof")
