            if not _chain_checkpoint_bundle_is_truthful(
                diff_content["before_root"], before_members
            ):
                return False
            if not _chain_checkpoint_bundle_is_truthful(
                diff_content["after_root"], after_members
            ):
                return False
            for change in change_entries:
                for change_proof in (change["before"], change["after"]):
                    if change_proof is not None and not (
                        _checkpoint_chain_checkpoint_is_truthful(change_proof)
                    ):
                        return False
            payload = {
                key: diff_content[key]
                for key in _CHECKPOINT_CHAIN_BUNDLE_DIFF_REPORT_KEYS[:5]
            }
            canonical = json.dumps(
                payload, ensure_ascii=False, separators=(",", ":")
